package main

import (
	"bufio"
	"fmt"
	"os"
)

var c, d, n, m, k, commonParty, must int

func main() {
	in := bufio.NewReader(os.Stdin)
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	fmt.Fscan(in, &c, &d, &n, &m, &k)

	commonParty = n * m
	must = commonParty - k

	if must > 0 {
		algorithmC := algC()
		algorithmD := algD()

		algJoint := algorithmC - c
		partyCMinusRound := (algJoint / c) * n

		i := must - partyCMinusRound
		for i > 0 {
			i--
			algJoint += d
		}

		fmt.Fprintln(out, min(algorithmC, algorithmD, algJoint))
	} else {
		fmt.Fprintln(out, 0)
	}
}

func algC() int {
	tempCommonParty := must
	sumTask := 0

	for tempCommonParty > 0 {
		tempCommonParty -= n
		sumTask += c
	}

	return sumTask
}

func algD() int {
	tempCommonParty := must
	sumTask := 0

	for tempCommonParty > 0 {
		tempCommonParty--
		sumTask += d
	}

	return sumTask
}

func algFull() int {
	algorithmC := algC()
	algorithmD := algD()

	sumTask := algorithmC - n
	partyCMinusRound := algorithmC * (n - 1)

	i := must - partyCMinusRound
	for i > 0 {
		i--
		sumTask += d
	}

	return min(algorithmC, algorithmD, sumTask)
}

func min(numbers ...int) int {
	minNumber := int(^uint(0) >> 1)

	for _, number := range numbers {
		if number < minNumber {
			minNumber = number
		}
	}

	return minNumber
}

